// Parse pesan masuk dari Fonnte
const body = $input.first().json;
const sender = body.sender || '';
const message = (body.message || '').trim().toLowerCase();
const device = body.device || '';

// Default: MID, tanggal hari ini
const today = new Date();
const yyyy = today.getFullYear();
const mm = String(today.getMonth() + 1).padStart(2, '0');
const dd = String(today.getDate()).padStart(2, '0');
const tanggal = `${yyyy}-${mm}-${dd}`;

let lembagaKey = 'MID';
let filterStatus = null; // null = semua

// Deteksi lembaga
if (message.includes('mtsd') || message.includes('mts d') || message.includes('mts-d')) {
  lembagaKey = 'MTsD';
}

// Deteksi tanggal format YYYY-MM-DD
const tglMatch = message.match(/(\d{4}-\d{2}-\d{2})/);
if (tglMatch) {
  return [{ json: { sender, tanggal: tglMatch[1], lembagaKey, filterStatus } }];
}

// Deteksi keyword
if (message.includes('alpa')) {
  filterStatus = 'A';
} else if (message.includes('hadir')) {
  filterStatus = 'H';
} else if (message.includes('izin')) {
  filterStatus = 'I';
} else if (message.includes('belum')) {
  filterStatus = '';
} else {
  filterStatus = null;
}

return [{ json: { sender, tanggal, lembagaKey, filterStatus } }];

// Filter & Format jawaban
const fbData = $input.first().json;
const ctx = $input.first().item.json.previousParse || {};

// Ambil data dari node sebelumnya (simpan di workflow data)
const allItems = $input.all();
const parseNode = allItems.find(i => i.node.name === 'Parse Pesan');
const { sender, tanggal, lembagaKey, filterStatus } = parseNode ? parseNode.json : {};

if (!fbData || typeof fbData !== 'object') {
  return [{ json: { sender, message: '⚠️ Data absensi tidak ditemukan untuk tanggal tersebut.' } }];
}

const records = Object.values(fbData).filter(r => r && typeof r === 'object');

let filtered = records;
if (filterStatus !== null) {
  if (filterStatus === '') {
    filtered = records.filter(r => !r.status);
  } else {
    filtered = records.filter(r => r.status === filterStatus);
  }
}

const labelStatus = filterStatus === 'H' ? 'Hadir' : filterStatus === 'I' ? 'Izin' : filterStatus === 'A' ? 'Alpa' : 'Belum diisi';
const emojiStatus = filterStatus === 'H' ? '✅' : filterStatus === 'I' ? '🟡' : filterStatus === 'A' ? '🔴' : '⚪';

let pesan = `📋 *Laporan Absensi ${lembagaKey}*\n📅 ${tanggal}\n`;
if (filterStatus !== null) {
  pesan += `${emojiStatus} ${labelStatus}: ${filtered.length} orang\n`;
} else {
  const h = records.filter(r => r.status === 'H').length;
  const i = records.filter(r => r.status === 'I').length;
  const a = records.filter(r => r.status === 'A').length;
  const b = records.filter(r => !r.status).length;
  pesan += `✅ Hadir: ${h}  🟡 Izin: ${i}  🔴 Alpa: ${a}  ⚪ Belum: ${b}\n`;
}
pesan += '━━━━━━━━━━━━━━━━━\n';

if (filtered.length === 0) {
  pesan += 'Tidak ada data untuk filter ini.';
} else {
  const grouped = {};
  filtered.forEach(r => {
    const key = r.guru || 'Unknown';
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(r);
  });
  Object.keys(grouped).sort().forEach(guru => {
    pesan += `👤 ${guru}\n`;
    grouped[guru].forEach(r => {
      pesan += `  ▫️ ${r.jam || ''} • ${r.kelas || ''} • ${r.mapel || ''}\n`;
    });
  });
}
pesan += '━━━━━━━━━━━━━━━━━\n_Dibot Absensi MID & MTsD_';

return [{ json: { sender, message: pesan } }];
